import re
from decimal import Context, Decimal, Inexact, InvalidOperation, localcontext

MAX_AMOUNT = Decimal("1000000.00")
_CENT = Decimal("0.01")
# Plain decimal: optional sign, ASCII digits, optional fractional part. No
# whitespace, exponents, underscores, or non-finite spellings.
_PLAIN_DECIMAL = re.compile(r"[+-]?(?:[0-9]+(?:\.[0-9]*)?|\.[0-9]+)\Z")


def _exact_context():
    # Private context: enough precision for any in-range amount, and trap
    # anything that would round or is invalid. Never touches the global one.
    return Context(prec=50, traps=[Inexact, InvalidOperation])


def to_cents(value):
    """Validate a finite Decimal and return it quantized to exponent -2.

    Raises ValueError if it is not positive, exceeds MAX_AMOUNT, or is not
    exactly representable in cents.
    """
    if not value.is_finite():
        raise ValueError("amount must be finite")
    if value <= 0:
        raise ValueError("amount must be positive")
    if value > MAX_AMOUNT:
        raise ValueError("amount exceeds maximum")
    with localcontext(_exact_context()):
        try:
            return value.quantize(_CENT)
        except (Inexact, InvalidOperation):
            raise ValueError("amount is not representable in cents") from None


def parse_amount(value):
    if isinstance(value, bool) or isinstance(value, float):
        raise ValueError("unsupported amount type")
    if isinstance(value, Decimal):
        dec = value
    elif isinstance(value, int):
        dec = Decimal(value)
    elif isinstance(value, str):
        if not _PLAIN_DECIMAL.match(value):
            raise ValueError("invalid amount string")
        dec = Decimal(value)
    else:
        raise ValueError("unsupported amount type")
    return to_cents(dec)


def format_amount(value):
    return format(value, ".2f")
EOF
